const raw = $input.first().json;
const headers = raw.headers || {};
const body = raw.body ?? raw;
const event = String(body.event || 'unknown');
const caseId = body.caseId || body.case_id || null;
const workspaceId = body.workspaceId || body.workspace_id || null;
const title = body.title || body.caseTitle || 'Caso jurídico';
const secretary = body.secretary || body.n8nSecretary || {};
const extras = body.extras || {};
const traceId = body.trace_id || `lex_${caseId || 'na'}_${Date.now()}`;

const clientWa = secretary.clientWhatsApp || secretary.client_whatsapp || null;
const lawyerWa = Array.isArray(secretary.lawyerWhatsApp)
  ? secretary.lawyerWhatsApp
  : (secretary.lawyer_whatsapp ? [secretary.lawyer_whatsapp] : []);
const allowedRecipients = Array.isArray(body.allowedRecipients)
  ? body.allowedRecipients.filter(Boolean)
  : [...lawyerWa.filter(Boolean), clientWa].filter(Boolean);

const prefs = secretary.preferences || {};
const clientOptOut = Boolean(prefs.clientOptOut || secretary.clientOptOut);
const lawyerOptOut = Boolean(prefs.lawyerOptOut || secretary.lawyerOptOut);

return [{
  json: {
    source: 'webhook',
    event,
    caseId,
    workspaceId,
    title,
    secretary,
    clientWa,
    lawyerWa: lawyerWa.filter(Boolean),
    allowedRecipients,
    clientOptOut,
    lawyerOptOut,
    extras,
    traceId,
    lexBase: ($env.LEX_API_BASE_URL || 'http://host.docker.internal:3000').replace(/\/$/, ''),
    needsConfigure: event === 'secretary.configure',
    needsCommand: event === 'secretary.command',
    notifyClient: !clientOptOut && !!clientWa && allowedRecipients.includes(clientWa) && !['secretary.configure','secretary.command'].includes(event),
    notifyLawyer: !lawyerOptOut && lawyerWa.length > 0 && allowedRecipients.length > 0
  }
}];

const res = $input.first().json;
const rows = Array.isArray(res.cases) ? res.cases : [];
if (!rows.length) return [];
return rows.map(row => {
  const meta = row.metadataJson || {};
  const sec = meta.n8nSecretary || {};
  const lawyers = Array.isArray(row.lawyerWhatsApp) ? row.lawyerWhatsApp : (Array.isArray(sec.lawyerWhatsApp) ? sec.lawyerWhatsApp : []);
  const clientWa = row.clientWhatsApp || sec.clientWhatsApp || null;
  const allowedRecipients = Array.isArray(row.allowedRecipients) ? row.allowedRecipients.filter(Boolean) : lawyers.filter(Boolean);
  return {
    json: {
      source: 'cron',
      event: 'cron.stalled',
      caseId: row.id,
      workspaceId: row.workspaceId,
      title: row.title,
      status: row.status,
      clientWa,
      lawyerWa: lawyers.filter(Boolean),
      allowedRecipients,
      clientOptOut: Boolean(sec.preferences?.clientOptOut),
      lawyerOptOut: Boolean(sec.preferences?.lawyerOptOut),
      extras: { stalledSince: row.updatedAt },
      traceId: `lex_cron_${row.id}_${Date.now()}`,
      lexBase: ($env.LEX_API_BASE_URL || 'http://host.docker.internal:3000').replace(/\/$/, ''),
      needsConfigure: false,
      needsCommand: false,
      notifyClient: false,
      notifyLawyer: lawyers.length > 0 && allowedRecipients.length > 0 && !sec.preferences?.lawyerOptOut
    }
  };
});

let ctx;
try {
  ctx = $('Parse Lex Event').first().json;
} catch (_) {
  ctx = $('Map cron → eventos').first().json;
}
const rawSnap = $input.first().json;
const snap = rawSnap && !rawSnap.error && (rawSnap.facts || rawSnap.brain) ? rawSnap : {};
const brain = snap.brain || snap.metadata?.brain || {};
const readiness = brain.proceduralReadiness || {};
const event = ctx.event;

const templates = {
  'case.created': {
    lawyer: `Novo caso no Lex: «${ctx.title}». Abra a entrevista e anexe documentos quando possível.`,
    client: `Olá! Seu atendimento jurídico foi registrado. Em breve nossa equipe retorna com orientações.`
  },
  'intake.saved': {
    lawyer: `Entrevista salva no caso «${ctx.title}». Revise partes/fatos quando quiser organizar com IA.`,
    client: null
  },
  'intake.structured': {
    lawyer: `A IA estruturou o relato do caso «${ctx.title}». Confira Fatos e partes antes de gerar peça.`,
    client: null
  },
  'document.indexed': {
    lawyer: `Documento processado no caso «${ctx.title}».`,
    client: `Recebemos um documento do seu atendimento. Nossa equipe está analisando.`
  },
  'brain.consolidated': {
    lawyer: `Case Brain atualizado — «${ctx.title}». Prontidão: ${readiness.score ?? '—'}% (${readiness.status || 'n/d'}).`,
    client: null
  },
  'draft.generated': {
    lawyer: `Minuta gerada — «${ctx.title}». Revise no Lex (Peças e minutas). Versão: ${ctx.extras.draftVersion ?? 'última'}.`,
    client: null
  },
  'review.completed': {
    lawyer: `Revisão concluída — «${ctx.title}». Veredito: ${ctx.extras.verdict || 'ver no Lex'}.`,
    client: ctx.extras.verdict?.includes('Quase') ? `Seu processo teve avanço interno. A equipe entrará em contato se precisar de algo.` : null
  },
  'strategy.updated': {
    lawyer: `Estratégia registrada no caso «${ctx.title}».`,
    client: null
  },
  'cron.stalled': {
    lawyer: `Lembrete Lex: caso «${ctx.title}» sem movimentação recente. Verifique documentos ou revisão pendente.`,
    client: null
  }
};

const t = templates[event] || {
  lawyer: `Atualização Lex — «${ctx.title}» (${event}).`,
  client: null
};

const factsCount = (snap.facts || []).length;
const partiesCount = (snap.parties || []).length;
const contextHint = `Fatos: ${factsCount}; Partes: ${partiesCount}; Pendentes entrevista: ${ctx.extras.checklistMissing ?? '—'}.`;

return [{
  json: {
    ...ctx,
    draftLawyer: t.lawyer + (event !== 'case.created' ? `\n${contextHint}` : ''),
    draftClient: t.client,
    snapshotOk: !snap.error
  }
}];

