parameters.jsCode:
const base = $('Montar rascunhos').first().json;
const llm = $input.first().json;
let lawyerMsg = base.draftLawyer;
let clientMsg = base.draftClient;
try {
  const text = llm.choices?.[0]?.message?.content || '';
  const m = text.match(/\{[\s\S]*\}/);
  if (m) {
    const p = JSON.parse(m[0]);
    if (p.lawyer) lawyerMsg = String(p.lawyer).slice(0, 500);
    if (p.client !== undefined) clientMsg = p.client ? String(p.client).slice(0, 500) : null;
  }
} catch (_) {}

const allowed = new Set((base.allowedRecipients || []).map(p => String(p).replace(/\D/g, '')));
const canSend = (to) => {
  if (!to || allowed.size === 0) return false;
  return allowed.has(String(to).replace(/\D/g, ''));
};

const out = [];
if (base.notifyLawyer && lawyerMsg) {
  for (const to of base.lawyerWa) {
    if (canSend(to)) out.push({ json: { ...base, channel: 'lawyer', to, message: lawyerMsg } });
  }
}
if (base.notifyClient && clientMsg && canSend(base.clientWa)) {
  out.push({ json: { ...base, channel: 'client', to: base.clientWa, message: clientMsg } });
}
if (!out.length) {
  out.push({ json: { ...base, channel: 'none', skipped: true } });
}
return out;

